                'The one exception to "articles are altered by special resolution" is the maximum number of shares — ordinary resolution (s88(3)). Questions test exactly this exception, and note s85(2) makes that clause optional in the first place.',
                's86 runs member-to-member as well as member-to-company; a member can enforce the articles against another member directly (s86(2)(c)).',
                'Money owed under the articles is a specialty debt (s86(3)) — which matters for limitation.',
                's80(3) is the provision that makes "adopted with modifications" work: the Model Articles fill every gap the registered articles do not exclude or modify.',
