                      's538(1)(c) — by general notice: that the director has an interest in a specified body corporate or firm (or is connected with a specified person) and is to be regarded as interested in any transaction entered into with it after the notice\'s effective date; s538(5) it must state the nature and extent of that interest or the nature of the connection.',
