                'For a sealable document, set out both permitted routes and then say which these facts allow — and if the seal route is chosen, name the Board decision (MA81(1)) and the MA81(4) signatories.',
                'Name the actual signatories by reference to s127(3)(a) or (b)(i) or (b)(ii), rather than saying "two officers".',
