                      'Participation in decision-making through CO and Model Articles rights, including the reserved powers.',
                      'Generally no return of capital except on a reduction of capital or in liquidation — and in liquidation, creditors rank ahead of shareholders.',
                      's134 — the shares are personal property; the member has no direct interest in the company\'s assets.',
                      'Distributions are confined to the s297(2) fund: accumulated realised profits not previously utilised, less accumulated realised losses not previously written off.',
