                      'The assignment must be absolute — not conditional, and not of part of the debt only.',
                      'It must be in writing signed by the assignor, the lending shareholder (in practice, executed as a deed).',
                      'Express notice in writing must be given to the debtor company.',
                      'Where it is executed as a deed and the assignor is a company, all three s128(1) limbs apply: executed in accordance with s127, expressed to be executed as a deed, and delivered as a deed (delivery presumed under s128(2)).',
