                      's591(1)-(2) — an article is VOID so far as it excludes the right to demand a poll (except on electing the chairperson or an adjournment), or makes ineffective a demand by at least 5 members entitled to vote, by member(s) representing at least 5% of total voting rights, or by the chairperson; s591(3)-(4) a proxy may demand or join in demanding a poll, and counts.',
                      's593 — a member need not vote the same way on all the shares they hold.',
                      'MA43(2) — the chairperson has a second or casting vote on an equality of votes.',
