                'In each, count the directors, count the quorum, and then count how many are actually able to act — that is usually where the obstacle is. Keep MA11(1), MA12 and MA8(4) apart: an inquorate meeting may still vote to call another meeting, MA12 bites only when the TOTAL number of directors is below quorum, and MA8(4) blocks a unanimous decision when the eligible directors would not form a quorum.',
